{
  "vulnerable_symbols": [],
  "trigger": "Node.js 应用使用带凭据的代理发起请求并启用自动重定向，当攻击者控制的初始服务器将请求重定向到不再经过该代理的目标时触发。",
  "preconditions": [
    "运行在 Node.js 环境并使用 Axios 的 http adapter",
    "配置了带凭据的代理（如 HTTP_PROXY/HTTPS_PROXY 或 proxy 含 user:pass）",
    "自动重定向启用（maxRedirects 大于 0）",
    "重定向目标不再经过该代理（如 https 目标且 HTTPS_PROXY 未设置或 NO_PROXY 匹配）",
    "初始请求目标可被攻击者控制并返回重定向"
  ],
  "exploit_evidence": [
    {
      "src": 2,
      "kind": "poc",
      "quote": "Includes proof of concept details, patch analysis for both v1.x and v0.x lines, and practical detection strategies."
    }
  ],
  "fixed_version": "1.16.0",
  "summary_zh": "Axios 1.7.4 在 Node.js 认证代理请求自动重定向到非代理目标时，可能泄露代理凭据，升级至 1.16.0。"
}
